def is_perfect_square(num):
    lo, hi = 1, num
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        sq = mid * mid
        if sq == num:
            return True
        if sq < num:
            lo = mid + 1                # candidate too small, search larger
        else:
            hi = mid - 1                 # candidate too large, search smaller
    return False

