    static boolean isPerfectSquare(int num) {
        long lo = 1, hi = num;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            long sq = mid * mid;
            if (sq == num) return true;
            if (sq < num) lo = mid + 1;      // too small, search larger
            else hi = mid - 1;                // too large, search smaller
        }
        return false;
    }
}

